package com.omnia.backend.service.impl;
import com.omnia.backend.dto.response.PlatformReportResponse.*;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class PlatformReportCalculatorTest {
    private final LocalDate today=LocalDate.of(2026,10,30);
    private PlatformReportWindow window(){return PlatformReportWindow.resolve(today.minusDays(6),today,7,today);}
    private PlatformReportEvent event(LocalDate day,Long id,String revenue,long orders){return new PlatformReportEvent(day,id,new BigDecimal(revenue),orders);}
    @Test void presetContainsExactlyThirtyUtcCalendarDays(){var w=PlatformReportWindow.resolve(null,null,30,today);assertEquals(LocalDate.of(2026,10,1),w.start());assertEquals(LocalDate.of(2026,9,1),w.previousStart());assertEquals(LocalDate.of(2026,9,30),w.previousEnd());assertEquals(today.plusDays(1),w.exclusiveEnd());}
    @Test void customLeapRangeAndPreviousLength(){var w=PlatformReportWindow.resolve(LocalDate.of(2024,2,28),LocalDate.of(2024,3,1),30,today);assertEquals(3,w.days());assertEquals(LocalDate.of(2024,2,25),w.previousStart());assertEquals(LocalDate.of(2024,2,27),w.previousEnd());}
    @Test void invalidPartialReversedFutureAndOversizedRangesRejected(){assertThrows(IllegalArgumentException.class,()->PlatformReportWindow.resolve(today,null,30,today));assertThrows(IllegalArgumentException.class,()->PlatformReportWindow.resolve(today,today.minusDays(1),30,today));assertThrows(IllegalArgumentException.class,()->PlatformReportWindow.resolve(today,today.plusDays(1),30,today));assertThrows(IllegalArgumentException.class,()->PlatformReportWindow.resolve(today.minusDays(366),today,30,today));assertThrows(IllegalArgumentException.class,()->PlatformReportWindow.resolve(null,null,5,today));}
    @Test void missingDaysAreZeroFilledWithoutInventedActivity(){var r=PlatformReportCalculator.aggregate(window(),null,null,List.of(),List.of(),0,0,0,0);assertEquals(7,r.daily().size());assertTrue(r.daily().stream().allMatch(d->d.revenue().signum()==0&&d.orders()==0));assertEquals(0,r.metrics().revenue().current().signum());assertEquals(0,r.metrics().revenue().changePercent().signum());}
    @Test void comparesEqualPeriodsAndExcludesOutOfBounds(){var w=window();var events=List.of(event(w.previousStart(),1L,"50",2),event(w.start(),1L,"100",4),event(w.end(),1L,"25",1),event(w.previousStart().minusDays(1),1L,"9000",900),event(w.exclusiveEnd(),1L,"9000",900));
        var r=PlatformReportCalculator.aggregate(w,null,null,List.of(new OrganizationChoice(1L,"One",null)),events,3,1,2,1);assertEquals(new BigDecimal("125"),r.metrics().revenue().current());assertEquals(new BigDecimal("50"),r.metrics().revenue().previous());assertEquals(new BigDecimal("150.0"),r.metrics().revenue().changePercent());assertEquals(new BigDecimal("5"),r.metrics().orders().current());}
    @Test void companyScopeCannotIncludeOtherCompanyOrLegacyRows(){var events=List.of(event(today,1L,"100",2),event(today,2L,"999",9),event(today,null,"888",8));var r=PlatformReportCalculator.aggregate(window(),1L,"One",List.of(new OrganizationChoice(1L,"One",null),new OrganizationChoice(2L,"Two",null)),events,1,0,0,0);assertEquals(new BigDecimal("100"),r.metrics().revenue().current());assertEquals(1,r.companies().size());assertEquals(1L,r.companies().get(0).id());assertEquals(new BigDecimal("100.00"),r.companies().get(0).sharePercent());}
    @Test void legacyRevenueIsVisibleAndCompanySumReconciles(){var events=List.of(event(today,1L,"80",2),event(today,null,"20",1));var r=PlatformReportCalculator.aggregate(window(),null,null,List.of(new OrganizationChoice(1L,"One",null),new OrganizationChoice(2L,"Zero",null)),events,0,0,0,0);assertEquals(3,r.companies().size());BigDecimal sum=r.companies().stream().map(Company::revenue).reduce(BigDecimal.ZERO,BigDecimal::add);assertEquals(r.metrics().revenue().current(),sum);assertTrue(r.companies().stream().anyMatch(c->c.id()==0&&c.revenue().compareTo(new BigDecimal("20"))==0));}
    @Test void paymentDateAndOrderCreationDateStayIndependent(){var events=List.of(event(today,1L,"40",0),event(today.minusDays(2),1L,"0",1));var r=PlatformReportCalculator.aggregate(window(),null,null,List.of(),events,0,0,0,0);assertEquals(0,r.daily().get(6).orders());assertEquals(new BigDecimal("40"),r.daily().get(6).revenue());assertEquals(1,r.daily().get(4).orders());}
    @Test void noInventedGrowthWhenPreviousIsZero(){assertNull(PlatformReportCalculator.metric(BigDecimal.TEN,BigDecimal.ZERO).changePercent());assertEquals(0,PlatformReportCalculator.metric(BigDecimal.ZERO,BigDecimal.ZERO).changePercent().signum());assertEquals(new BigDecimal("-50.0"),PlatformReportCalculator.metric(BigDecimal.TEN,BigDecimal.valueOf(20)).changePercent());}
}
